package openapi_test

// The composition proof — and, now that the monolith is gone, the ONLY producer
// of the published spec.
//
// TestFleetIsTheCompositionOfItsApps composes every app's own subset — each generated by
// that app's own binary from that app's own router (`<app> openapi`) — into the
// fleet document, and requires it to equal private.yaml byte for byte, and its
// public projection to equal openapi.yaml. There is no fully-mounted binary left
// to read: "compose the apps" and "the spec" are one statement. `make describe`
// writes both through this same compose (-compose); with no flag the same compose is
// the check.
//
// What it proves is COMPOSITION and only composition: that the subsets compose
// without two apps claiming one address or one schema name, and that the golden
// is what they compose to. Both sides are derived, so it cannot prove either is
// still the routes — `make -f mk/fleet.mk check` regenerates them from
// source for that, and manifest/router_test.go asks the router whether the fleet
// delivers what they describe. Three questions, three gates, each answered where
// its answer lives.
//
// It links no subsystem and mounts nothing but the openapi endpoint itself, so
// it costs a second and runs on every push.

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/hanzoai/cloud/manifest"
	"github.com/hanzoai/cloud/openapi"
	"sigs.k8s.io/yaml"
)

// composeOut writes the composed document — everything the fleet serves. It is the
// SOLE writer of both artifacts now that the monolith is gone: `make describe`
// regenerates each app's subset and then runs this with -compose to compose them,
// which writes the composed document at the named path and its public projection
// beside it. Without the flag the same compose is the drift gate.
var composeOut = flag.String("compose", "", "write the composed document to this path (regenerate both artifacts)")

// privatePath, publicPath, floorPath and specDir are relative to this package's
// directory.
//
// TWO ARTIFACTS, ONE COMPOSITION, AND THE NAME SAYS WHICH IS WHICH. openapi.yaml is the
// PUBLIC contract — the customer surface, the name every developer, SDK generator
// and spec-reading tool reaches for, so it is the document a user deals with.
// private.yaml is the INTERNAL one: everything the fleet serves, admin family and
// alpha capabilities included, which is what an operator reads and what the
// routing gates measure.
//
// They are written by one run of one compose and compared by one test, so the two
// can never describe different commits — which they would the moment a second
// command produced the second file.
const (
	privatePath = "../private.yaml"
	publicPath  = "../openapi.yaml"
	floorPath   = "floor.json"
	untypedPath = "untyped.json"
	specDir     = "../plugin"
)

// render is the one encoding both goldens are written in, so a difference
// between them is never a difference in how they were serialised.
func render(d *openapi.Document) ([]byte, error) {
	j, err := json.Marshal(d)
	if err != nil {
		return nil, err
	}
	return yaml.JSONToYAML(j)
}

// fromTree is the WORKING TREE's copy of one app's subset — the files
// check has just regenerated from source and is about to compare against.
// The host reads the same files through plugin.Spec, embedded at build time;
// openapi.Subsets decodes either, so there is one decoder and one compose whichever
// end you enter from.
//
// It reads them and nothing else. WHERE a path is routed is not a question a
// document can answer, and the version of this function that tried is why the
// fleet published 58 unreachable paths: it skipped any path already present in
// the composed document — the artifact this test protects — so the artifact exempted
// every defect it already contained, and what survived that was reported with t.Logf.
// A gate that reads its own output cannot fail. The question moved to the only
// thing that can answer it, the router: manifest/router_test.go.
func fromTree(app string) []byte {
	raw, err := os.ReadFile(filepath.Join(specDir, app, "openapi.json"))
	if err != nil {
		return nil // openapi.Subsets refuses it by name
	}
	return raw
}

func TestFleetIsTheCompositionOfItsApps(t *testing.T) {
	want, err := os.ReadFile(privatePath)
	if err != nil {
		t.Fatalf("read %s: %v — run `make describe`", privatePath, err)
	}
	subsets, err := openapi.Subsets(manifest.Names(), fromTree, manifest.StageOf)
	if err != nil {
		t.Fatal(err)
	}
	// The SAME composition the host serves (cmd/cloud spec → openapi.MountFleet),
	// which is what makes the served document and this golden one document rather
	// than two that agree today.
	composed, err := openapi.Fleet(subsets)
	if err != nil {
		t.Fatalf("compose: %v", err)
	}

	// THE RATCHET, before anything is written: a regeneration that publishes less
	// than the committed floor is refused in BOTH modes, so `make describe` cannot
	// be the thing that lands a shrunken document. See openapi/floor.go.
	was, err := openapi.ReadFloor(floorPath)
	if err != nil {
		t.Fatal(err)
	}
	raised, err := was.Raise(openapi.Measure(composed))
	if err != nil {
		t.Fatal(err)
	}

	// THE TWIN RATCHET, and it is a different question: the floor asks whether the
	// document still PUBLISHES what it did, this asks how much of it a client can
	// CALL. A document can clear the floor while a larger share of it becomes
	// undispatchable, because a raw route is a published operation. See
	// openapi/untyped.go.
	rawWas, err := openapi.ReadUntyped(untypedPath)
	if err != nil {
		t.Fatal(err)
	}
	rawNow, err := rawWas.Shrink(openapi.Count(composed))
	if err != nil {
		t.Fatal(err)
	}

	got, err := render(composed)
	if err != nil {
		t.Fatalf("yaml: %v", err)
	}

	// THE PUBLIC PROJECTION, out of the SAME composed document. It is derived here
	// rather than by a second command for the reason the whole package exists: two
	// producers of one fact are two facts, free to be generated at different
	// commits and to disagree about which operations the API has.
	pub, err := openapi.Publish(composed)
	if err != nil {
		t.Fatalf("publish: %v", err)
	}
	pubGot, err := render(pub)
	if err != nil {
		t.Fatalf("yaml (public): %v", err)
	}

	// -compose is the REGENERATE mode (write the goldens and stop); no flag is the
	// GATE mode (verify below). Falling through would compare the just-written
	// document against the golden we read BEFORE writing it, and fail every real
	// regeneration for having done its job.
	//
	// The public contract is written BESIDE whatever -compose named, never at its
	// own flag: a second flag is a second thing to forget, and the run that forgot
	// it would leave the document every SDK is generated from describing last
	// week's surface.
	if *composeOut != "" {
		if err := os.WriteFile(*composeOut, got, 0o644); err != nil {
			t.Fatalf("write %s: %v", *composeOut, err)
		}
		out := filepath.Join(filepath.Dir(*composeOut), filepath.Base(publicPath))
		if err := os.WriteFile(out, pubGot, 0o644); err != nil {
			t.Fatalf("write %s: %v", out, err)
		}
		// The floor is raised from the INTERNAL document and from nothing else —
		// see TestTheFloorGuardsTheInternalDocument for why measuring the public
		// one would disarm it in a single run.
		if err := raised.Write(floorPath); err != nil {
			t.Fatalf("write %s: %v", floorPath, err)
		}
		// Written from the INTERNAL document for the floor's reason: the public
		// projection drops the admin family and every staged capability, so
		// measuring that one would let a raw route land in /v1/admin unseen.
		if err := rawNow.Write(untypedPath); err != nil {
			t.Fatalf("write %s: %v", untypedPath, err)
		}
		t.Logf("wrote %s (%d paths), %s (%d paths), %s (%d products) and %s (%d undispatchable)",
			*composeOut, len(composed.Paths), out, len(pub.Paths),
			floorPath, len(raised.Products), untypedPath, rawNow.Operations)
		return
	}

	// The monolith is gone: the composed document IS the published spec, so this is a
	// plain golden check. A byte for byte match is the whole guarantee — any
	// difference means a route moved (an app subset regenerated) without the
	// golden being regenerated too, or the reverse.
	if !bytes.Equal(got, want) {
		t.Fatalf("private.yaml is not the compose of its apps' subsets (%d paths composed now). A route was added, "+
			"removed or renamed and either an app subset or the internal document was not regenerated. "+
			"Run `make describe` and commit the result.", len(composed.Paths))
	}

	// And the same check for the public contract, which is the one that matters
	// in the OTHER direction: a diff here is either a product that stopped being
	// published or one that started, and both are decisions somebody makes on
	// purpose. This is the whole ratchet for the public surface — it is small
	// enough to compare WHOLE, so it needs no counting scheme (openapi/floor.go)
	// to notice a shrink, and it notices growth too.
	wantPub, err := os.ReadFile(publicPath)
	if err != nil {
		t.Fatalf("read %s: %v — run `make describe`", publicPath, err)
	}
	if !bytes.Equal(pubGot, wantPub) {
		t.Fatalf("openapi.yaml is not the public projection of the composed document (%d paths public now, out of "+
			"%d). An operation was added to or removed from the published contract — every public SDK, the "+
			"public CLI, the MCP tool list and docs.hanzo.ai are generated from this file. If that was the "+
			"intent, run `make describe` and commit it next to the openapi.Public line that caused it.",
			len(pub.Paths), len(composed.Paths))
	}
	t.Logf("composed %d paths / %d schemas / %d tags from %d apps — byte-identical to %s; %d paths public (%s)",
		len(composed.Paths), schemaCount(composed), len(composed.Tags), len(manifest.Apps), privatePath,
		len(pub.Paths), publicPath)
}

// THE FLOOR GUARDS THE INTERNAL DOCUMENT. Pointing it at the public one would not
// fail — it would pass, quietly, and take the ratchet with it.
//
// floor.json is the only thing that can tell a smaller API from a smaller
// document, and it works by refusing a regeneration that publishes less than the
// last one. The public projection publishes, by construction, a tiny fraction of
// the same surface. Measure THAT and one of two things happens: the run is
// refused for a shrink that is not a shrink and CI is wedged, or somebody
// "fixes" it by rewriting floor.json from the public numbers — after which every
// internal product could vanish and the floor, now sized to eighteen paths,
// would agree that nothing was lost.
//
// So this asserts both halves: the committed floor is the internal document's,
// and feeding it the public one is REFUSED. The second is the load-bearing one —
// it is the assertion that fails if the ratchet is ever re-based.
func TestTheFloorGuardsTheInternalDocument(t *testing.T) {
	subsets, err := openapi.Subsets(manifest.Names(), fromTree, manifest.StageOf)
	if err != nil {
		t.Fatal(err)
	}
	composed, err := openapi.Fleet(subsets)
	if err != nil {
		t.Fatalf("compose: %v", err)
	}
	pub, err := openapi.Publish(composed)
	if err != nil {
		t.Fatalf("publish: %v", err)
	}
	was, err := openapi.ReadFloor(floorPath)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := was.Raise(openapi.Measure(composed)); err != nil {
		t.Fatalf("the committed floor refuses the INTERNAL document, which is the document it is "+
			"supposed to describe: %v", err)
	}
	if _, err := was.Raise(openapi.Measure(pub)); err == nil {
		t.Fatalf("the committed floor ACCEPTS the public projection (%d paths against the internal "+
			"document's %d). It is therefore not sized to the internal surface, and a regeneration that "+
			"lost most of the API would pass it", len(pub.Paths), len(composed.Paths))
	}
}

// Two apps may not claim one address. This is the check the manifest's
// call-graph walk found the need for: clients/git's /:org/:repo catch-all was
// swallowing other apps' routes, and a merge that picked a winner would have
// published a document describing a fleet nobody deploys.
func TestComposeRefusesTwoAppsAtOneAddress(t *testing.T) {
	dup := func(app, path string) openapi.Part {
		return openapi.Part{App: app, Doc: &openapi.Document{
			Paths: map[string]openapi.PathItem{path: {"get": {OperationID: "get_" + app}}},
		}}
	}
	_, err := openapi.Compose([]openapi.Part{dup("git", "/v1/x"), dup("code", "/v1/x")})
	var c *openapi.Conflict
	if !errors.As(err, &c) {
		t.Fatalf("Compose = %v, want a *Conflict — a silent last-write-wins is the bug this exists to refuse", err)
	}
	if c.Kind != "operation" || c.A != "git" || c.B != "code" {
		t.Errorf("Conflict = %+v, want operation GET /v1/x between git and code", c)
	}
	// The same address in ONE app is not a conflict — an app's own document
	// already had to be injective to be generated at all.
	if _, err := openapi.Compose([]openapi.Part{dup("git", "/v1/x"), dup("code", "/v1/y")}); err != nil {
		t.Errorf("two apps at two addresses: %v", err)
	}
}

// One schema name, two shapes. Schemas are named after Go types (AccessOut,
// Campaign, None), so two apps CAN reach the same name honestly — and every
// generated SDK would bind whichever the merge read last.
func TestComposeRefusesOneSchemaNameWithTwoShapes(t *testing.T) {
	part := func(app string, schema any) openapi.Part {
		return openapi.Part{App: app, Doc: &openapi.Document{
			Paths:      map[string]openapi.PathItem{"/v1/" + app: {"get": {OperationID: "get_" + app}}},
			Components: &openapi.Components{Schemas: map[string]any{"None": schema}},
		}}
	}
	_, err := openapi.Compose([]openapi.Part{
		part("ad", map[string]any{"type": "object"}),
		part("crm", map[string]any{"type": "string"}),
	})
	var c *openapi.Conflict
	if !errors.As(err, &c) {
		t.Fatalf("Compose = %v, want a *Conflict", err)
	}
	if c.Kind != "schema" || c.Name != "None" {
		t.Errorf("Conflict = %+v, want schema None", c)
	}

	// Identical shapes are ONE schema, not a conflict: two apps using the same
	// type is composition working, not colliding.
	same := map[string]any{"type": "object", "properties": map[string]any{"ok": map[string]any{"type": "boolean"}}}
	doc, err := openapi.Compose([]openapi.Part{part("ad", same), part("crm", same)})
	if err != nil {
		t.Fatalf("identical schemas: %v", err)
	}
	if n := schemaCount(doc); n != 1 {
		t.Errorf("schemas = %d, want 1 — an identical definition must merge, not duplicate", n)
	}
}

// The composed document owes the same invariant a generated one does. Two apps
// at two addresses whose ids collide is a defect composition can introduce even
// when neither app is at fault.
func TestComposeRefusesCollidingOperationIDs(t *testing.T) {
	fixed := func(app, path string) openapi.Part {
		return openapi.Part{App: app, Doc: &openapi.Document{
			Paths: map[string]openapi.PathItem{path: {"get": {OperationID: "get_thing"}}},
		}}
	}
	if _, err := openapi.Compose([]openapi.Part{fixed("a", "/v1/a"), fixed("b", "/v1/b")}); err == nil {
		t.Fatal("Compose accepted a duplicate operationId — a generator would mis-consume the document")
	}
}

// PROVENANCE: every operation names the registry that registered it, so a
// misplaced one names a repo to file against instead of costing a bisect of 116
// subsets. Written where it is known and never overwritten — an operation that
// arrived through a relay already knows better than the part it arrived in.
func TestComposeNamesTheRegistryBehindEachOperation(t *testing.T) {
	doc, err := openapi.Compose([]openapi.Part{
		{App: "ai", Doc: &openapi.Document{Paths: map[string]openapi.PathItem{
			"/v1/ai/health":        {"get": {OperationID: "a"}},
			"/v1/chat/completions": {"post": {OperationID: "b", App: "github.com/hanzoai/ai"}},
		}}},
	})
	if err != nil {
		t.Fatal(err)
	}
	if got := doc.Paths["/v1/ai/health"]["get"].App; got != "ai" {
		t.Errorf("x-app = %q, want the app that contributed the part", got)
	}
	if got := doc.Paths["/v1/chat/completions"]["post"].App; got != "github.com/hanzoai/ai" {
		t.Errorf("x-app = %q, want the module behind the relay — the compose overwrote a registry that had already named itself", got)
	}
}

// A RELAY YIELDS TO A SPECIFIC ROUTE, because that is what the matcher does. This
// is the one overlap Compose resolves, and it resolves it by reading the router's
// rule off the data — a relayed operation names its own registry, a direct one
// does not — rather than by preferring an app.
func TestComposeGivesTheSpecificRouteWhatTheMatcherGivesIt(t *testing.T) {
	specific := openapi.Part{App: "provisioning", Doc: &openapi.Document{Paths: map[string]openapi.PathItem{
		"/v1/search": {"post": {OperationID: "provisioningSearch"}},
	}}}
	relayed := openapi.Part{App: "ai", Doc: &openapi.Document{Paths: map[string]openapi.PathItem{
		"/v1/search": {"post": {OperationID: "aiSearch", App: "github.com/hanzoai/ai"}},
	}}}
	for _, order := range [][]openapi.Part{{specific, relayed}, {relayed, specific}} {
		doc, err := openapi.Compose(order)
		if err != nil {
			t.Fatalf("%s first: %v", order[0].App, err)
		}
		if got := doc.Paths["/v1/search"]["post"].OperationID; got != "provisioningSearch" {
			t.Errorf("%s first: operationId = %q, want the specific route — the relay's handler never runs at that address",
				order[0].App, got)
		}
	}

	// Two RELAYS at one address is still a refusal: two wildcards overlapping is a
	// bug at the composition root and there is no rule that picks between them.
	both := func(app, src string) openapi.Part {
		return openapi.Part{App: app, Doc: &openapi.Document{Paths: map[string]openapi.PathItem{
			"/v1/x": {"get": {OperationID: "get_" + app, App: src}},
		}}}
	}
	_, err := openapi.Compose([]openapi.Part{both("ai", "github.com/hanzoai/ai"), both("iam", "github.com/hanzoai/iam")})
	var c *openapi.Conflict
	if !errors.As(err, &c) || c.Kind != "operation" {
		t.Fatalf("Compose = %v, want an operation Conflict between two relays", err)
	}
}

func schemaCount(d *openapi.Document) int {
	if d.Components == nil {
		return 0
	}
	return len(d.Components.Schemas)
}

// THE PUBLIC CONTRACT, READ AS THE ARTIFACT. Not the declarations, not the
// projection function — the committed file every public SDK, the public CLI, the
// MCP tool catalogue and docs.hanzo.ai are generated from.
//
// Checking the artifact rather than the config is the whole point. A whitelist
// that is right and a document that is wrong is the same outage as a whitelist
// that is wrong, and only one of the two is visible from the config.

// regenerating reports whether this run is WRITING the goldens rather than
// checking them. A test that reads a committed artifact must not run then: it
// would read the previous one, from before this run replaced it, which is the
// same trap TestFleetIsTheCompositionOfItsApps returns early to avoid.
func regenerating() bool { return *composeOut != "" }

// committed loads one of the two artifacts this compose writes.
func committed(t *testing.T, path string) *openapi.Document {
	t.Helper()
	if regenerating() {
		t.Skip("regenerate mode: the artifact is being rewritten by this run, so reading it would read the old one")
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v — run `make describe`", path, err)
	}
	j, err := yaml.YAMLToJSON(raw)
	if err != nil {
		t.Fatal(err)
	}
	var d openapi.Document
	if err := json.Unmarshal(j, &d); err != nil {
		t.Fatal(err)
	}
	return &d
}

// The public contract is the customer surface and nothing beside it: no
// operator product, no relay, no legacy spelling, nothing outside /v1.
// Checked BY NAME on the committed artifact rather than by counting, so a
// failure says what got out — and checked for the other direction too, because
// a contract that quietly lost a customer product is the SDK that cannot reach
// it.
func TestThePublicContractIsTheCustomerSurface(t *testing.T) {
	d := committed(t, publicPath)
	for path, item := range d.Paths {
		// The ROOT is inside the namespace, not outside it: /v1 is the index a
		// client that knows nothing else starts from, and a contract that dropped it
		// would generate clients unable to reach the index of their own API.
		if path != openapi.RootPath && !strings.HasPrefix(path, "/v1/") {
			t.Errorf("%s is outside /v1 and published in the public contract", path)
		}
		if strings.Contains(path, "{wildcard") {
			t.Errorf("%s is a relay and published in the public contract", path)
		}
		for method, op := range item {
			for _, tag := range op.Tags {
				if tag == openapi.Operator || tag == openapi.Compat {
					t.Errorf("%s %s is published in the public contract under %q",
						strings.ToUpper(method), path, tag)
				}
			}
		}
	}
	// The customer products a shrink would be worst in. Their ROOT is enough:
	// every one of these is a product a customer holds a key for.
	for _, root := range []string{"/v1/billing/balance", "/v1/git/repos", "/v1/iam/users", "/v1/kms/secrets",
		"/v1/chat/completions", "/v1/models", "/v1/projects", "/v1/commerce/product", "/v1/o11y/logs"} {
		if _, in := d.Paths[root]; !in {
			// Not every spelling above is guaranteed to exist forever; report the
			// absence and let the reader judge against the internal document.
			t.Logf("%s is not in the public contract — check it is not in private.yaml either", root)
		}
	}
}

// What lies outside the customer surface by the rule: the host's non-/v1
// furniture, the operator's address family, a relay. Each is in the
// internal document and none reaches the published one.
func TestThePublicContractDropsWhatIsOutsideTheRule(t *testing.T) {
	d := committed(t, publicPath)
	for _, path := range []string{
		"/health", "/", "/.well-known/openapi.json",
		"/v1/admin/orgs", "/v1/tasks/{wildcard1}",
	} {
		if _, published := d.Paths[path]; published {
			t.Errorf("%s reached the public contract", path)
		}
	}
}

// THE NAME IS THE AUDIENCE, and this is the property the two names exist to
// create.
//
// openapi.yaml is what a developer types, what an SDK generator defaults to and
// what a spec-reading tool finds first. Whatever it carries reaches every
// generated client, whether or not the generator has ever heard of the audience
// rule — hanzoai/openapi's publish.py projects this one file into every published
// SDK and filters by path, never by stage. So the file that name points at has to
// BE the customer contract, and that is checked here on the artifact rather than
// inferred from the projection that wrote it.
//
// Both directions, because either alone is satisfied by a pair that has collapsed
// into one document under two names: nothing alpha and nothing under the
// operator's family may reach openapi.yaml, and both must be present in
// private.yaml — which is where an operator and a flagged-in customer read them.
//
// The alpha capabilities are read off manifest.Apps rather than listed, so a
// capability that goes alpha next month is covered the day its row says so.
func TestAlphaAndAdminReachOnlyThePrivateDocument(t *testing.T) {
	pub, priv := committed(t, publicPath), committed(t, privatePath)

	// Read off the operation's OWN x-stage first, which covers every route
	// whatever capability serves it.
	for path, item := range pub.Paths {
		if openapi.Product(path) == openapi.Operator {
			t.Errorf("%s is the operator's product and is published in %s, which every SDK is generated from", path, publicPath)
		}
		for method, op := range item {
			if op.Stage != "" {
				t.Errorf("%s %s is %s and is published in %s", strings.ToUpper(method), path, op.Stage, publicPath)
			}
		}
	}

	// And again off the MANIFEST, by address, because the two are different
	// readings: x-stage is what the compose stamped, and a capability's row is what
	// the fleet says it is. A stamp that silently stopped being written would leave
	// the loop above asserting nothing at all.
	//
	// By row rather than by name, so a capability that is promoted to ga, renamed
	// or added is covered the day its row changes and this test needs no edit.
	staged, held := 0, 0
	for _, a := range manifest.Apps {
		if a.Stage == "" {
			continue
		}
		staged++
		for _, prefix := range a.Prefixes {
			for path := range pub.Paths {
				if under(path, prefix) {
					t.Errorf("%s is %s (%s) and reached %s", path, a.Stage, a.Name, publicPath)
				}
			}
			for path, item := range priv.Paths {
				if under(path, prefix) {
					held += len(item)
				}
			}
		}
	}

	// The other direction: the private document must carry what the public one
	// refuses, or the two artifacts have become one document under two names and
	// every assertion above passes by describing nothing.
	//
	// The operator's family is unconditional — the fleet always serves one. A
	// staged capability is not: every capability being ga is a legitimate state of
	// the manifest, so that half is asserted only when there is something to
	// assert, and says so when there is not.
	admin := 0
	for path := range priv.Paths {
		if openapi.Product(path) == openapi.Operator {
			admin++
		}
	}
	if admin == 0 {
		t.Errorf("%s carries no %s path — the operator surface is published nowhere, so the check "+
			"above passed by finding nothing rather than by keeping it out", privatePath, openapi.Operator)
	}
	switch {
	case staged == 0:
		t.Logf("every capability is ga: no staged surface to keep out of %s today", publicPath)
	case held == 0:
		t.Errorf("%d capabilities are staged and %s carries no operation from any of them — an "+
			"operator and a flagged-in customer read them there, so they are published nowhere", staged, privatePath)
	}
	t.Logf("%d public paths carry no staged capability and no /v1/%s; %s carries %d operator paths "+
		"and %d operations from %d staged capabilities",
		len(pub.Paths), openapi.Operator, privatePath, admin, held, staged)
}

// under reports whether an address is a prefix's own or sits beneath it.
func under(path, prefix string) bool {
	return path == prefix || strings.HasPrefix(path, prefix+"/")
}

// Two names that differ only in CASE are one name to every generator that
// PascalCases a schema, so the gate owes them the same refusal it owes one name
// with two shapes. It is the same defect one level down, and it is not
// hypothetical: `call` (meet's media room) and `Call` (tel's telephony call)
// were both claimed, and the Kotlin client imported ai.hanzo.cloud.model.Call
// beside okhttp3.Call and stopped compiling on an ambiguous import.
func TestComposeRefusesTwoNamesThatDifferOnlyInCase(t *testing.T) {
	part := func(app, schema string) openapi.Part {
		return openapi.Part{App: app, Doc: &openapi.Document{
			Paths: map[string]openapi.PathItem{"/v1/" + app: {"get": {OperationID: "get_" + app}}},
			Components: &openapi.Components{Schemas: map[string]any{
				schema: map[string]any{"type": "object"},
			}},
		}}
	}
	_, err := openapi.Compose([]openapi.Part{part("meet", "call"), part("tel", "Call")})
	var c *openapi.Conflict
	if !errors.As(err, &c) {
		t.Fatalf("Compose = %v, want a *Conflict — `call` and `Call` are one class to Kotlin", err)
	}
	if c.Kind != "case" {
		t.Errorf("Conflict.Kind = %q, want \"case\" (got %+v)", c.Kind, c)
	}
	for _, want := range []string{"call", "Call", "meet", "tel"} {
		if !strings.Contains(c.Error(), want) {
			t.Errorf("Conflict.Error() = %q, does not name %q — a refusal nobody can act on", c.Error(), want)
		}
	}

	// The SAME name twice is not a case collision — it is the shape gate's
	// business, and identical shapes merge.
	if _, err := openapi.Compose([]openapi.Part{part("meet", "call"), part("tel", "call")}); err != nil {
		t.Errorf("one name claimed twice with one shape: %v — that is composition, not collision", err)
	}

}
